package dev.falix.studiomobile;
import java.io.*;import java.util.concurrent.TimeUnit;import org.json.*;import okhttp3.*;
/** A non-retrying, explicit one-place upload. Only server versionNumber is confirmation. */
final class PublishService {
 static final class Result {long version;String type;Result(long v,String t){version=v;type=t;}}
 static Request request(String key,long universe,long place,File file,boolean publish)throws Exception{if(universe<=0||place<=0)throw new IOException("Link a valid Universe ID and Place ID first.");if(file.length()<=0||file.length()>RobloxApi.MAX_DOWNLOAD||!RobloxApi.validPlace(file))throw new IOException("Invalid or oversized place file.");String type=RobloxApi.xmlPlace(file)?"application/xml":"application/octet-stream";return new Request.Builder().url(RobloxApi.ROOT+"/universes/v1/"+universe+"/places/"+place+"/versions?versionType="+(publish?"Published":"Saved")).header("x-api-key",key).header("Accept","application/json").post(RequestBody.create(file,MediaType.get(type))).build();}
 static Result parse(String body,boolean publish)throws Exception{JSONObject o=new JSONObject(body);long v=o.optLong("versionNumber",0);if(v<=0)throw new IOException("Roblox did not return a version number. Upload is unconfirmed; check Creator Dashboard before retrying.");return new Result(v,publish?"Published":"Saved");}
 static Result upload(RobloxApi.Session s,long universe,long place,File file,boolean publish)throws Exception{OkHttpClient client=NetworkRuntime.client().newBuilder().retryOnConnectionFailure(false).callTimeout(180,TimeUnit.SECONDS).readTimeout(90,TimeUnit.SECONDS).writeTimeout(90,TimeUnit.SECONDS).build();try(Response response=client.newCall(request(s.key,universe,place,file,publish)).execute()){if(!response.isSuccessful())throw new IOException("Roblox rejected the upload (HTTP "+response.code()+"). Check universe-places:write, target IDs, edit access and publishing eligibility. Your local project was kept.");if(response.body()==null||response.body().contentLength()>1024*1024)throw new IOException("Upload response could not be verified.");try(InputStream in=response.body().byteStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>1024*1024)throw new IOException("Upload response too large.");out.write(b,0,n);}return parse(out.toString("UTF-8"),publish);}}catch(java.net.SocketTimeoutException e){throw new IOException("Upload timed out. Roblox may have received it; check Creator Dashboard before retrying. No automatic retry was sent.");}}
}
